{'content': '$fn = 100;

// Dimensions
base_radius = 16;
top_radius = 14;
neck_radius = 9.5;
height = 50;

difference() {
    // Main Body Construction using Rotate Extrude of a Profile
    rotate_extrude()
    polygon(points=[
        [0, 0],
        [base_radius, 0],           
        [base_radius, 3],           // Base vertical
        [base_radius - 1, 5],       // Chamfer/Curve
        [base_radius - 1, 8],       // Base Ring
        [base_radius - 2, 10],      // Step in
        [neck_radius + 2, 12],      // Lower curve transition
        [neck_radius, 30],          // Neck (narrowest point)
        [neck_radius + 1, 35],      // Start of flare
        [top_radius - 0.5, 38],     // Underside of turret
        [top_radius, 38],           // Turret rim bottom
        [top_radius, height],       // Turret side vertical
        [0, height]                 // Top Cap
    ]);

    // Top indentation (The bowl)
    translate([0, 0, height])
    sphere(r = top_radius * 0.7);

    // Crenellations (Battlements)
    // 6 merlons = 6 slots. 
    // We cut slots using cubes.
    // For 6 slots evenly spaced, we need 6 cuts relative to the center.
    // However, a centered cube cuts *two* slots (opposite sides).
    // So we need 3 rotations: 0, 60, 120.
    for (angle = [0 : 60 : 179]) { 
        rotate([0, 0, angle])
        translate([0, 0, height])
        // Cut dimension: Width=5mm, Length=Long, Depth=5mm
        cube([5, top_radius * 3, 7], center=true);
    }
}
